[{"order":1,"type":"heading","text":"Session Management and Store Configuration in Express.js"},{"order":2,"type":"paragraph","text":"Session management is a crucial aspect of web development. It allows web applications to maintain state across multiple requests from the same user. In Express.js, this is typically handled using the express-session middleware."},{"order":3,"type":"subheading","text":"Prerequisites and Installation"},{"order":4,"type":"paragraph","text":"To get started, you need to install express and express-session. In a production environment, you should also use a dedicated session store rather than the default MemoryStore."},{"order":5,"type":"code","text":"npm install express express-session connect-redis redis"},{"order":6,"type":"subheading","text":"Basic Session Setup"},{"order":7,"type":"paragraph","text":"Here is how you configure basic session handling in your Express application. By default, sessions are stored in memory, which is not suitable for production."},{"order":8,"type":"code","text":"const express = require('express');
const session = require('express-session');

const app = express();

app.use(session({
  secret: 'your-super-secret-key',
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false, maxAge: 3600000 }
}));

app.get('/', (req, res) => {
  if (req.session.views) {
    req.session.views++;
    res.send('Views: ' + req.session.views);
  } else {
    req.session.views = 1;
    res.send('Welcome to the session demo. Refresh!');
  }
});

app.listen(3000);"},{"order":9,"type":"subheading","text":"Configuring a Production-Ready Store (Redis)"},{"order":10,"type":"paragraph","text":"MemoryStore leaks memory and does not scale across multiple server instances. For production, you should use a persistent store like Redis."},{"order":11,"type":"code","text":"const express = require('express');
const session = require('express-session');
const RedisStore = require('connect-redis').default;
const { createClient } = require('redis');

const app = express();

// Initialize client.
const redisClient = createClient();
redisClient.connect().catch(console.error);

// Initialize store.
const redisStore = new RedisStore({
  client: redisClient,
  prefix: 'myapp:'
});

app.use(session({
  store: redisStore,
  resave: false,
  saveUninitialized: false,
  secret: 'production-secret-key',
  cookie: {
    secure: true, // Set to true if using HTTPS
    httpOnly: true,
    maxAge: 1000 * 60 * 60 * 24 // 1 day
  }
}));

app.get('/login', (req, res) => {
  req.session.userId = 42;
  res.send('Logged in successfully');
});

app.listen(3000);"},{"order":12,"type":"subheading","text":"Security Best Practices"},{"order":13,"type":"bullet_point","text":"Secret: Use a strong, randomly generated string or environment variable for the session secret."},{"order":14,"type":"bullet_point","text":"Cookie Secure: Always set cookie.secure to true in production when utilizing HTTPS to prevent man-in-the-middle attacks."},{"order":15,"type":"bullet_point","text":"HttpOnly: Keep httpOnly set to true to prevent client-side scripts from accessing the cookie via document.cookie."},{"order":16,"type":"bullet_point","text":"Store Scaling: Avoid MemoryStore in production environments to prevent memory leaks and support horizontal scaling."}]
